      "passage": "孔子為這個弟子與眾不同的難馴感到驚訝。單是好勇厭柔，不少人也是如此，但像子路一樣輕蔑事物形式的人卻很罕見。「禮」雖然最終歸結於精神，卻必須從形式進入。「禮云禮云，玉帛云乎哉？樂云樂云，鐘鼓云乎哉？」當孔子這麼講時，他非常樂意傾聽，但一說明禮樂細則，他立刻顯得一臉無趣。一邊要與這種逃避形式主義的本能搏鬥，一邊又要傳授他禮樂，即使對孔子來說，也是困難重重。（改寫自中島敦〈弟子〉）",
