      "pass": 0.75,
      "disc": 31,
      "passage": "〔公告〕行政院衛生署公告（署授藥字第0940002424號）：自94年5月1日起，禁止中藥用硃砂製造、調劑、輸入、輸出、販賣或陳列。〔中醫師說明〕炮製藥用硃砂須重複水飛法多次方可，耗時費力；若不肖者私下以機器研磨，會因機器運轉的高溫使硃砂產生劇毒，一旦入藥極其危險。〔硃砂加工，古文參考《天工開物》、《本草綱目》〕水飛：惟取好砂，軋碎如微塵，入缸注清水澄浸。過三日夜，其上浮者不堪入藥，傾入別缸；其下沉結者，曬乾即頭朱也。升煉：次砂不入藥，作爐置砂於中，下承以水，上覆以盆，器外加火，則煙飛於上，水銀溜於下。丹砂性寒而無毒，入火則熱而有毒，能殺人。水銀乃至陰毒物，因火煅丹砂而出，或加鹽、礬煉而為輕粉，或加硫黃升而為銀朱。",
