      "passage": "背景知識就像個篩網，網越細密，新知識越不會流失；例如同樣去聽一場演講，有人獲益良多，有人一無所獲，最主要的原因是語音像一陣風，只有綿密的網才可以兜住它。背景知識又像個架構，有了架子，新進來的知識才知道往哪兒安放，當每個格子都放滿了，一個完整的圖形就會顯現出來，一個新的概念於焉誕生。心理學有個著名的實驗：把一盤殘棋給西洋棋生手看二分鐘，然後要他把這盤棋重新排出來，他無法做到；但是給西洋棋大師看同樣長的時間，則能正確地將棋子重新排出來。是大師的記憶力比較好嗎？當然不是，因為當我們把一盤隨機安放的棋子給大師看，請他重排時，他的表現就跟生手一樣了。大師和生手唯一的差別就在於有背景知識，使得殘棋變得有意義，意義度減輕了記憶的負擔。背景知識所建構出的基模會主動去搜尋已存的有用資訊，將新獲得的知識放在適當的位置上，組合成有意義的東西，一個沒有意義的東西會很快就淡出我們的知覺系統。（改寫自洪蘭《哈啦與抓虱的語言‧序》）",
