      "disc": 41,
      "passage": "人生識字憂患始，姓名粗記可以休。何用草書誇神速，開卷惝怳令人愁。我嘗好之每自笑，君有此病何能瘳。自言其中有至樂，適意無異逍遙遊。近者作堂名醉墨，如飲美酒消百憂。乃知柳子語不妄，病嗜土炭如珍羞。（節錄自蘇軾〈石蒼舒醉墨堂〉。惝怳：惆悵；瘳：病癒；柳子：柳宗元）",
      "stem": "關於詩中石蒼舒之「病」，敘述最適當的是：",
