      "explain": "蘇軾以「病何能瘳」戲說石蒼舒嗜書成癡，實則讚美他「其中有至樂，適意無異逍遙遊」，是以調侃寄寓稱美，故選D。詩中並無擔心招禍、寄託不遇或自慚不及之意，A、B、C皆誤。",
