      "passage": "余嘗論畫，以為人禽宮室器用皆有常形。至於山石竹木、水波煙雲，雖無常形而有常理。常形之失，人皆知之。常理之不當，雖曉畫者有不知。故凡可以欺世而取名者，必託於無常形者也。雖然，常形之失，止於所失，而不能病其全，若常理之不當，則舉廢之矣。以其形之無常，是以其理不可不謹也。世之工人，或能曲盡其形，而至於其理，非高人逸才不能辨。（蘇軾〈淨因院畫記〉）",
