      "passage": "<p>甲、臺城六代競豪華，結綺臨春事最奢。萬戶千門成野草，只緣一曲後庭花。（劉禹錫〈臺城〉。臺城：宮禁所在地。）</p><p>乙、鹿耳潮落吼聲遲，閱盡興亡眼力疲。惆悵騎鯨人去後，江山今又屬阿誰。（謝鯉魚〈鹿耳門懷古〉。騎鯨：相傳鄭成功騎乘白鯨轉世。）</p>",
