      "disc": 48,
      "passage": "<p><b>老子</b>：失道而後德，失德而後仁，失仁而後義，失義而後禮。夫禮者，忠信之薄而亂之首。</p><p><b>孔子</b>：禮云禮云，玉帛云乎哉？樂云樂云，鐘鼓云乎哉？</p><p><b>吳子良（宋代學者）</b>：蓋聃之於禮，尚其意不尚其文，然使文而可廢，則意亦不能獨立矣。此（指「禮者，忠信之薄而亂之首」）老子鑑文之弊，而矯枉過正之言也。</p><p><b>朱熹的學生問</b>：老子云「夫禮，忠信之薄而亂之首」，孔子又卻問禮於他，不知何故？</p><p><b>朱熹答</b>：他曾為柱下史，故禮自是理會得，所以與孔子說得如此好。只是他又說這箇物事不用得亦可，一似聖人用禮時反若多事，所以如此說。〈禮運〉中「謀用是作，而兵由此起」等語，便自有這箇意思。</p>",
