      "disc": 36,
      "stem": "「純貴妃不認為自己的『雅』會輸給魏瓔珞的『俗』，卻又無可奈何。她發現弘曆留在鍾粹宮的日子越來越少，去延禧宮的日子越來越多，就好像世間一切俗人，偶爾管弦絲竹，但多數時候還是要柴米油鹽。」這段文字既揭示「雅」、「俗」對比，也運用「管弦絲竹」、「柴米油鹽」的比喻強化語意。下列文句，使用比喻方式強化對比作用的是：",
