        "B": "就在那光與色的動晃中，忽然那太陽，像巨大的蛋黃，像橘紅淋漓的一團烙鐵漿，蹦跳而出，雲彩炫耀。世界彷彿一時間豁然開朗，山脈谷地於是有了較分明的光影",
