      "disc": 23,
      "passage": "過了一天非人的生活，到了夜晚想做一件人做的事：睡覺。但是，不忙著睡，寶貝蚊子來了。雙方的工作不外下列幾種：（一）蚊子奏細樂。（二）我揮手致敬。（三）樂止。（四）休息片刻。（五）是我不當心，皮膚碰了蚊子的嘴，奇痛。（六）蚊子奏樂。（七）我揮手送客。清晨醒來，察視一夜工作的痕迹，常常發現腿部作玉蜀黍狀。有時候面部略微改變一點形狀，例如：嘴唇加厚，鼻樑增高。據腦筋靈敏的人說，若備一床帳子，則蚊子自然不作入幕之賓。但我已和太太商量就緒，在下月發薪之前，無論如何，我們仍然要保持大國民的態度，對蚊子絕不排斥。（改寫自梁實秋〈蚊子與蒼蠅〉）",
