      "passage": "血管賁張的想像，都在史料閱讀之際平息下來，過多的熱情也被迫必須冷卻。歷史的想像，在古典顏色的紙頁之間穿梭，以求得假想中的一個事實。但是，在千錘百鍊的考據下獲得的事實，果真是屬於事實？頹然坐在浩瀚的史書之前，忽然覺悟所謂事實不都是解釋出來的？史料與史料的銜接，如果需要人工著手構築，如何證明事實值得信賴？歷史想像求得的事實，如何不是想像的延伸？內心自我提問的過程，一旦陷入之後，時間之旅便無窮無盡。對於歷史書寫，越來越覺得恐懼。（陳芳明〈書寫就是旅行〉）",
