      "disc": 27,
      "passage": "甲、古者以天下為主，君為客，凡君之所畢世而經營者，為天下也；今也以君為主，天下為客，凡天下之無地而得安寧者，為君也。是以其未得之也，屠毒天下之肝腦，離散天下之子女，以博我一人之產業，曾不慘然！　乙、凡將立國，制度不可不察也，治法不可不慎也，國務不可不謹也，事本不可不摶也。制度時，則國俗可化，而民從制。治法明，則官無邪。國務壹，則民應用。事本摶，則民喜農而樂戰。　丙、處大國不攻小國，處大家不篡小家，強者不劫弱，貴者不傲賤，多詐者不欺愚。此必上利於天，中利於鬼，下利於人。三利，無所不利，故舉天下美名加之，謂之聖王。",
