      "disc": 30,
      "passage": "名片的種類式樣之多，就如同印名片的人一樣。有足以令人發笑的，有足以令人駭怕的，也有足以令人哭不得笑不得的。把各式的名片聚集起來，恐怕比香菸裡的畫片還更有趣。　官僚的名片，時行的是單印名姓，不加官銜。其實官做大了，人就自然出名，官銜的名片簡直用不著。惟獨有一般不大不小的人物，印起名片來，深恐自己的姓名太輕太賤，壓不住那薄薄的一張紙，於是把古往今來的官銜一齊的印在名片上，望上去黑糊糊的一片，就好像一個人的背上馱起一塊大石碑。　身通洋務，或將要身通洋務的先生，名片上的幾個英文字是少不得的，「湯姆」、「查利」都成，甚而再冠上一個聲音相近的外國姓。因為名片也者，乃是一個人的全部人格的表現。（梁實秋〈名片〉。畫片：早期菸商為宣傳產品並防止香菸折損，在菸盒中放置的小圖片。）",
      "stem": "閱讀下文，選出敘述正確的選項：",
