      "passage": "<p>甲、藏書畫者，多取空名，偶傳為鍾、王、顧、陸之筆，見者爭售，此所謂「耳鑒」。又有觀畫而以手摸之，相傳以謂色不隱指者為佳畫，此又在耳鑒之下，謂之「揣骨聽聲」。（沈括《夢溪筆談》。鍾、王、顧、陸：指鍾繇、王羲之、顧愷之、陸探微，皆魏晉南北朝書畫家。色不隱指：意謂畫面看似立體，手指觸覺卻平滑。）</p><p>乙、書畫之妙，當以神會，難可以形器求也。世之觀畫者，多能指摘其間形象、位置、彩色瑕疵而已，至於奧理冥造者，罕見其人。如彥遠《畫評》言：「王維畫物，多不問四時，如畫花，往往以桃、杏、芙蓉、蓮花同畫一景。」（沈括《夢溪筆談》）</p>",
