      "passage": "【甲】每患遷、固以來，文字繁多，自布衣之士，讀之不遍，況於人主，日有萬機，何暇周覽！臣常不自揆，欲刪削冗長，舉撮機要，專取關國家盛衰，繫生民休戚，善可為法，惡可為戒者，為編年一書，……上起戰國，下終五代，凡一千三百六十二年，修成二百九十四卷。【乙】予在京師，因借館閣諸公家藏數本，參校之，蓋十正其六七，……其要皆主於利言之，合從連橫，變詐百出。然自春秋之後，以迄于秦，二百餘年興亡成敗之跡，粗見於是矣！雖非義理之所存，而辯麗橫肆，亦文辭之最，學者所不宜廢也。",
