      "disc": 46,
      "passage": "曾子寢疾，病。樂正子春坐於床下，曾元、曾申坐於足，童子隅坐而執燭。童子曰：「華而睆，大夫之簀與？」子春曰：「止！」曾子聞之，瞿然曰：「呼！」曰：「華而睆，大夫之簀與？」曾子曰：「然。斯季孫之賜也，我未之能易也。元，起，易簀。」曾元曰：「夫子之病革矣！不可以變。幸而至於旦，請敬易之。」曾子曰：「爾之愛我也不如彼。君子之愛人也以德，細人之愛人也以姑息。吾何求哉？吾得正而斃焉，斯已矣。」舉扶而易之，反席未安而沒。（《禮記‧檀弓》。睆：明亮。簀：席子。）",
