      "explain": "文中翟公巽截取《漢書》《論語》語句、各補一字並改「文子」為「父子」，卻讓「讀者不覺其補」，正是化用典籍而渾然天成、不留斧鑿痕跡，選D。A重點不在刪削；B恰恰是仿用古人語而非獨出機杼；C並無藉古諷今之意。",
