      "passage": "文學和社會發展密不可分。元明之交，出現一些揭露社會弊病的作品，如劉基（A）《郁離子》運用故事呈現其政治主張，形式承襲《世說新語》，屬志人筆記小說。及至晚明，受到王陽明心學的影響，袁宏道主張文學要「獨抒性靈，不拘格套」，（B）〈晚遊六橋待月記〉上繼〈黃州快哉亭記〉的小品形式，詳述當日遊蹤。在戲曲方面，則有湯顯祖的「情至觀」，（C）《牡丹亭》透過女性嚮往愛情的故事，呈現反禮教的思想，為其理論的實踐。明末清初，黃宗羲以（D）〈原君〉推究設立君主制度的本義，可視為對心學的批判。",
