      "disc": 34,
      "passage": "鏡之工列十鏡於賈區，發奩而視，其一皎如，其九霧如。或曰：「良苦之不侔甚矣。」工解頤謝曰：「非不能盡良也。蓋賈之意，唯售是念。今來市者，必歷鑒周睞，求與己宜。彼皎者不能隱芒杪之瑕，非美容不合，是用什一其數也。」予感之，作〈昏鏡詞〉：昏鏡非美金，漠然喪其晶。陋容多自欺，謂若它鏡明。瑕疵既不見，妍態隨意生。一日四五照，自言美傾城。飾帶以紋繡，裝匣以瓊瑛。秦宮豈不重，非適乃為輕。（劉禹錫〈昏鏡詞并引〉）",
