// 109 學年度指定科目考試 國文考科（選擇題 42 題：單選 34、多選 8）
// 來源：大學入學考試中心官方試題本＋選擇題參考答案＋國文科答對率及鑑別度表（皆官方 PDF/XLS）
// pass=官方全體到考答對率(多選題為官方得分率)；disc=官方鑑別度D；explain 為本站自製教學解析
