      "explain": "B對應「謂疫無傳染…其實不然，是以聞者莫之信」——謊稱不傳染既不可信也解決不了問題；E對應文末「染與不染繫乎人心之邪正、氣體之虛實」——身心素質不同，未必都染病。A文中無「隔離處所太遠」之說；C朱熹認為以「利害」相勸一旦染病即失信，並不可取；D他主張一律「曉以恩義」而非分明理／無知兩套，故A、C、D皆不合，選B、E。此題得分率僅27%，是多選最難。",
