      "passage": "法蘭克福是大多數外國旅客到德國的第一站，除了巨大繁忙的法蘭克福國際機場外，這裡也是德國的鐵、公路交通樞紐，以及歐陸的金融中心，更因是歐洲中央銀行的所在地，在世界經濟上的地位可謂舉足輕重。因為是銀行城，市區內現代的摩天大樓林立，使法蘭克福的天際線十分絢麗。除了工商業充斥，她也是一座文化古都。從1562年起，法蘭克福一直是神聖羅馬帝國皇帝加冕的地方，崇高的地位延續到該帝國1806年瓦解為止。旅行者可從市中心古色古香的羅馬山廣場，感受歐洲中古風情。法蘭克福位於美茵河畔，有廣大美麗的河濱綠園，可在此觀賞高聳壯觀的天際線。而美茵河往西匯入萊茵河，河流孕育出本區自然環境的旺盛生命力，造就無數美景。（改寫自林呈謙《德國旅行家》）",
