      "passage": "近十年來專注於犯罪小說的評論研究大幅增加，僅有少數提及犯罪小說的源起。有人認為閱讀犯罪小說的基本動機是宗教性的，透過儀式與象徵性的犧牲來除去個人或群體的罪惡。這種企盼並不會永遠奏效，真正的犯罪小說迷就像摩尼教徒，認為光明與黑暗會永無止境地相互抗衡，猶如偵探與罪犯的對峙。部落獻祭的人或許被視為是神聖的，因此通常在死亡前都必須經過偽裝，將人類外觀打扮成需驅趕的惡魔模樣。偵探小說的操作方式則相反，罪犯剛登場時是受認可的人物，而且往往受人敬重。這個面具要到故事最後才會被扯下來，露出違法者的真面目。偵探就像巫醫一樣神聖，能嗅出破壞社會的惡魔氣味，展開追捕，看破各式偽裝，直探事件根源。在故事中將偵探安排為凶手，通常會成為敗筆，除了這種作法顛覆法律外，信仰也是重要因素，因為這樣的安排混淆了光明與黑暗的力量。（改寫自朱利安‧西蒙斯《血腥謀殺》）",
