      "disc": 18,
      "passage": "根據馮‧弗里希的早期研究，蜜蜂有兩種「舞步」：一種他稱為環繞舞，一種則為8字搖擺舞。當時他的結論是：跳環繞舞，表示蜜蜂發現花蜜的來源；跳搖擺舞，則表示蜜蜂找到花粉。後來，波伊特勒持續進行研究，開始懷疑當初的論點。他和馮‧弗里希在1944年繼續做實驗，發現如果餵食盤距離蜂巢超過一百公尺，不管蜜蜂帶什麼東西回去，都會跳搖擺舞。所以他們認為：蜜蜂不同的舞蹈方式，並非用來描述發現什麼物質，而是一種用來傳達更複雜資訊的方法，也就是要說明地點。馮‧弗里希寫道：這種精確描述距離與方向的能力「似乎太過奇妙，根本不像是真的。」（改寫自修‧萊佛士《昆蟲誌：人類學家觀看蟲蟲的26種方式》）",
