      "disc": 7,
      "passage": "記得我當第一年住院醫師時，有一晚恰好遇到一個車禍外傷病人由救護車送來急診。經過詳細檢查，確認只有些皮肉裂傷，總住院醫師便決定把病人帶到開刀房，洗淨傷口加以縫合並住院觀察。當晚是我們的副主任湯普生醫師值班。由於總住院醫師認為這是很平常的外傷，而且他已處理得很好，因此決定讓湯普生醫師休息。誰知湯普生第二天巡房後走出病房就大發雷霆，把總醫師痛罵一頓，說他沒有依照科內規定，維護病人權益，未和主治醫師討論出最好的治療方法，也不尊重醫學倫理，因為病人在法律上屬於湯普生醫師，他有義務照護病人。事實上病人狀況相當穩定，總醫師卻因一個善意的疏忽，幾乎被記過甚至開除。（改寫自王國照《重披白袍》）",
