      "disc": 27,
      "passage": "人主之道，靜退以為寶。不自操事而知拙與巧，不自計慮而知福與咎。是以不言而善應，不約而善增。言已應則執其契，事已增則操其符。符契之所合，賞罰之所生也。故群臣陳其言，君以其言授其事，事以責其功。功當其事，事當其言，則賞；功不當其事，事不當其言，則誅。明君之道，臣不得陳言而不當。是故明君之行賞也，曖乎如時雨，百姓利其澤；其行罰也，畏乎如雷霆，神聖不能解也。故明君無偷賞，無赦罰。賞偷則功臣墮其業，赦罰則奸臣易為非。是故誠有功則雖疏賤必賞，誠有過則雖近愛必誅。疏賤必賞，近愛必誅，則疏賤者不怠，而近愛者不驕也。（《韓非子‧主道》）",
