      "passage": "現代漢語的被動句常以「被」加在動詞前（被騙），或用「被」引出施動者加於動詞前（被人騙）。文言可將「見」加在動詞前（是以見放），或用「於」引出施動者（此非孟德之困於周郎者乎），也可「見」和「於」兼用（蔡澤見逐於趙）；可見「見」在動詞前只能表被動，若要引出施動者，動詞後還需「於」。此外可用「為」引出施動者再加動詞（為天下笑），或省略施動者（使身死而為刑戮），也可「為……所」合成表被動（余時為桃花所戀），「為……所」式也可省略施動者（若屬皆且為所虜）。",
