    "G1": {
      "title": "文學評論：宇文所安《中國古典文學中的往事再現》（中西悲劇比較）",
      "passage": "<p>西方對於悲劇的定義，大多談到人的局限性——主角最終發現自己只不過是受更大的意志所支配的對象，但在必然性的驅使之下，仍無可奈何地走向毀滅。我們不必指望在中國的傳統裡發現西方意義上的悲劇，這種悲劇的結構是受文化限制的。不同的文明有各自不同的典型，我們可以在非道德的必然性與人的道德秩序的衝突中，發現中國的典型。中國傳統中非道德的必然性，通常是指周而復始的自然，是一種非人格的力量，人們稱之為「命」。相對於西方悲劇的必然性來說，最引人注目的對比，是這種必然性完全能夠為人所理解，而且每當不可避免的事情快要發生時，會出現許多徵兆，「命」往往通過這些徵兆顯示它的存在。西方的悲劇英雄總有一個從懵然無知到恍然大悟的過程；在中國，與悲劇英雄對應的人物常在既定的不幸結局來臨前，早就認識到這種結局是不可避免的。主角在這裡沒有抗爭，而是在註定要遭受不幸的情況下「知其不可而為之」，令人崇敬地克服絕望情緒。（改寫自宇文所安《中國古典文學中的往事再現》）</p>"
    },
    "G2": {
      "title": "語文常識：呂叔湘《文言虛字》論「其」",
      "passage": "<p>「其」可作「其中之」講，如：「孔融幼時，與諸兄食梨，取『其』小者。」「其」的這種用法可說是從「他的」之義變化出來，但也未嘗不可仍作「那個」講。「其」的這兩種意義本來密切相連，「他的」就等於「那個……的」。我們因為白話裡用的詞不同，就生出分別，古人大概感覺只有一個作為指稱之用的「其」。「其」還有一種用法，表示語氣。這和指稱用法毫無關係，應該是兩個不同的詞，只是寫成同一形式罷了。「其」表示的語氣，或為測度，和「殆」差不多，如：「始作俑者『其』無後乎？」或為勸勉，如：「爾『其』無忘乃父之志！」這個「其」和白話的「可」相當。（改寫自呂叔湘《文言虛字》）</p>"
    },
