      "passage": "<p><b>慶全庵桃花　謝枋得</b><br>尋得桃源好避秦，桃紅又見一年春。<br>花飛莫遣隨流水，怕有漁郎來問津。</p><p><b>桃花　徐孚遠</b><br>海山春色等閒來，朵朵還如人面開。<br>千載避秦真此地，問君何必武陵回。</p><p>【作者簡介】謝枋得，宋末元初人。1276 年率兵抗元，無援而敗。南宋滅亡後，隱居於福建，元朝曾數度徵聘，始終堅辭不應。1289 年，遭福建省參政強制送往京師，乃絕食五日而死。徐孚遠，明末清初人。明朝亡後，曾參與抗清之舉。1661 年隨鄭成功入臺，不久徙居廈門。1663 年，清軍攻陷廈門，徐孚遠擬攜眷返家鄉江蘇未果，滯留廣東，1665 年病故。</p>"
