      "passage": "《紅樓夢》作者透過神話與寓言的層層架構，創造了一個開天闢地的頑癡情種賈寶玉，以這個踽踽於洪荒的第一畸零人，來傳達他對生命的孤奇領悟。凡讀《紅樓夢》而真能為解人者，必能體味作者徘徊掙扎於傳統文化激流中之無奈與痛楚。作者創造了一個獨步古今的賈寶玉，其靈奇乖僻，完全處於傳統法度之外；其耽情溺色，更使天下視之若魔。這個賈寶玉是被幽禁於傳統文化心靈深處的禁忌與壓抑之大解放，故人亦以「混世魔王」稱之。《紅樓夢》以情為心的全盤架構，正契應湯顯祖「因情成夢，因夢成戲」、「世有有情之天下，有有法之天下」之說。在有法之天下中，有情之天下只能成其為夢，以寄諸於筆墨之間。賈寶玉癡魔怪僻的造型，固然是一種「情」的誇張強調、壓抑與反抗的姿態，然則另一面向，卻也依舊是一個掩飾的面具，一種畸零的姿態。故以之為魔為怪，為病為疴，正顯示正統禮法之約束力量依然存在。（改寫自張淑香〈頑石與美玉〉）",
