      "passage": "白靈〈及時雨〉：<br>滿江的濃墨自兩萬英尺的高空／瀉下，瀉──下／下到山頭丘陵盆地以及我家窗前卻是／烏雲洶湧／一似踢起煙塵萬丈／奔騰在宣紙下端的／萬匹黑馬／遲遲不肯下凡<br>新店溪的血壓正低／水龍頭們在我洗澡的當頭忽然／氣喘，太太守候門外的消防車旁叫著／水呀水呀／而昨天還在山上的／青潭直潭翡翠谷／今天都坐在報紙上飛進屋來<br>一道金鞭猛地抽了我眼睛一下／窗外千里之遠的山上馬蹄雷動／瞬間便殺到我浴室的窗前／為首的一匹，定睛看去／哎呀！好個宋江（宋江外號「及時雨」）",
