      "disc": 37,
      "passage": "紫衣侯論劍：我雖將天下所有劍法全部記住，我那師兄也能記得絲毫不漏，但他卻能在記住後又全都忘記，我卻萬萬不能，縱然想盡千方百計，卻也難忘掉其中任何一種。我那師兄將劍法全都忘記之後，方自大徹大悟，悟了「劍意」，他竟將心神全都融入了劍中，以意馭劍，隨心所欲。雖無一固定的招式，但信手揮來，卻無一不是妙到毫巔之妙著。也正因他劍法絕不拘囿於一定之形式，是以人根本不知該如何抵擋。我雖能使遍天下劍法，但我之所得，不過是劍法之形骸；他之所得，卻是劍法之靈魂。我的劍法雖號稱天下無雙，比起他來實是糞土不如！",
      "stem": "武俠小說論及武術武道，多受傳統文化影響。依據古龍《浣花洗劍錄》中紫衣侯對劍法的論述，可與其觀點相應的選項是：",
