      "disc": 17,
      "passage": "甲、秋燈明翠幕，夜案覽芸編。今來古往，其間故事幾多般。少甚佳人才子，也有神仙幽怪，瑣碎不堪觀。正是不關風化體，縱好也徒然。論傳奇，樂人易，動人難。知音君子，這般另作眼兒看：休論插科打諢，也不尋宮數調，只看子孝共妻賢。正是驊騮方獨步，萬馬敢爭先？（高明《琵琶記》〈水調歌頭〉）　乙、何元朗，一言兒啟詞中寶藏。道欲度新聲休走樣。名為樂府，須教合律依腔。寧使時人不鑑賞，無使人撓喉捩嗓。說不得才長。越有才，越當著意斟量。（沈璟〈二郎神‧論曲〉）",
