      "passage": "<p>社會上所發生的事件，古今是有其絕相類似之處的。生活經驗豐富，瞭解當代社會最深的史學家，是最能瞭解過去社會的史學家。社會上有些事件是可能發生的，有些事件是必不可能發生的。可能發生的事件，史學家在文獻足徵的情況下，可以確定其可信。必不可能發生的事件，史學家可以不顧前人言之鑿鑿，而斷然予以否認。所以鬼神怪誕之事，在原則上講，不入於史。現實生活經驗中所見不到的鬼神，如何能相信其出現於千百年以前呢？詩人詞客所幻想的離奇故事，如西王母住在為日月隱藏之所的崑崙山上，如何能是實錄呢？史學家一般認為「妖異止於怪誕，談諧止於取笑」，可以直刪不妨；而對於誦經獲報、符咒靈驗等等，不可盡以為誣妄，採取將信將疑的態度則差可，深信之不疑則必不可。（改寫自杜維運〈歷史想像與歷史真理〉）</p>"
