      "disc": 39,
      "passage": "惟是道理自有厚薄。比如身是一體，把手足捍頭目，豈是偏要薄手足？其道理合如此。禽獸與草木同是愛的，把草木去養禽獸，又忍得。人與禽獸同是愛的，宰禽獸以養親，與供祭祀，燕賓客，心又忍得。至親與路人同是愛的，如簞食豆羹，得則生，不得則死。不能兩全，寧救至親，不救路人，心又忍得。這是道理合該如此。（王陽明《傳習錄》）",
