      "passage": "文學家之意匠經營，其間如何創新，當然要在作者的想像與感情之是否觸到「前人所未道」處，見其分曉。但是，作者縱使有了那樣的新意，倘無適當的語言與之配合表出，結果仍不足構成文學批評對象的價值。因此，語言雖為文學批評對象之表層的客觀的事實，然而沒有這個事實，便也失去了那對象的存在。（王夢鷗《古典文學論探索》)",
