      "passage": "<p>那一夜，大雨如注。老人冒雨從外面回來，進入臥房，在燈亮起來的剎那，他發現沙發上坐著一個青年，手執左輪槍，正對準著他。「不許聲張！給我錢和你的汽車鑰匙！」老人一眼認出那把手槍是他自己的。他從容地關上門，傍著茶几坐了下來。「好大的雨，淋得我直打哆嗦，先讓我喝杯咖啡再商量吧！」「你敢耍花招！」「我不敢，我只是想暖暖身，你也來一杯吧。」老人倒了兩杯熱呼呼的咖啡。在喝的同時，他指著對方一身灰色的囚衣說：「哦，你是逃犯呀！好小子，我也在監牢裡待了三十年呢！」「想不到你這傢伙竟然也——」接著一陣冷笑。突然，外面一部汽車駛近。兩雙皮靴響上臺階，在門口停住。青年一躍而起，拿槍抵住老人腦袋：「開門你就別想活！」「外面是誰？」「是我們，趙英和李金，報告典獄長，109號新來的囚犯越獄逃跑。」「知道了，你們守住通道口，不許隨便離開！」「是，長官。」兩雙皮靴響下臺階。汽車在雨中遠去。「你瞧，我沒騙你吧！我也在監牢裡待了三十年。」老人趁勢奪下青年手中的槍：「孩子，你從來沒玩過手槍吧！我這把手槍已經二十年不上子彈了。」然後他把另一杯咖啡遞給對方。「喝掉它吧，乖乖地回到監獄去，我不會讓他們為難你的。」青年捧起杯子，艱難地嚥盡最後一口咖啡。他朝門走去時，老人塞給他一把雨傘，拍拍他的肩：「孩子，我明天一早去看你。」（改寫自 Cabinson Borges 作、丁樹南譯〈雨夜〉）</p>"
