      "passage": "<p>丞之職，所以貳令，於一邑無所不當問。其下主簿、尉，主簿、尉乃有分職。丞位高而偪，例以嫌不可否事。文書行，吏抱成案詣丞，卷其前，鉗以左手，右手摘紙尾，雁鶩行以進，平立，睨丞曰：「當署。」丞涉筆占位，署惟謹，目吏問可不可。吏曰：「得」，則退；不敢略省，漫不知何事。官雖尊，力勢反出主簿、尉下。諺數慢，必曰丞，至以相訾謷。丞之設，豈端使然哉！</p><p>博陵崔斯立，種學績文，以蓄其有，泓涵演迤，日大以肆。貞元初，挾其能，戰藝於京師，再進再屈千人。元和初，以前大理評事言得失黜官，再轉而為丞茲邑。始至，喟曰：「官無卑，顧材不足塞職。」既噤不得施用，又喟曰：「丞哉！丞哉！余不負丞而丞負余！」則盡枿去牙角，一躡故跡，破崖岸而為之。</p><p>丞廳故有記，壞漏污不可讀；斯立易桷與瓦，墁治壁，悉書前任人名氏。庭有老槐四行，南牆鉅竹千梃，儼立若相持；水㶁㶁循除鳴，斯立痛掃溉，對樹二松，日哦其間。有問者，輒對曰：「余方有公事，子姑去。」考功郎中知制誥韓愈記。（韓愈〈藍田縣丞廳壁記〉。偪：侵迫。訾謷：詆毀。枿：絕。㶁㶁：水聲。）</p>"
