      "passage": "舞蹈是一種身體的表現運動，桌球是一種體能運動的辯證舞蹈。杜甫看公孫大娘舞劍，有這麼兩句：「觀者如山色沮喪，天地為之久低昂」。中國文化傳統中居然還有這種為「身體的表現藝術」產生巨大震動的場面，簡直令人難以置信。待看到陳靜打球，才忽然體會，杜公此詩，並非應酬之作。她低身發球時冷眼覷著對方的神氣，有威懾感，她的反手快彈，命中率高，突然性強，經常打亂對方節奏。她的似從容實迅速的步法移位，她的正手拉球，基本上都是為反手的這一板做準備。比賽中的陳靜，都以反手的這一板作為成敗得失的焦點。她發球後，她的回擊準備位置，立即以反手拍的攻擊板型為重心，身體的其餘部位，從眼睛到腳尖，都為此配合。她的反手拍就是她的劍尖，她的全部意識都集中在這個致命武器最犀利的一點上。一九八八年漢城奧運會上，陳靜拿金牌的那一仗，這種反手帶出的威懾感，發揮到極致。那種威懾感，不是純機械的技術，而是氣勢，一如當年杜甫筆下公孫大娘的舞劍。（改寫自劉大任〈陳靜反手彈〉）",
