      "passage": "<p>登上這亭，在平日是可以近瞰西湖，遠望浙江，甚而至於縹緲的滄海的，可是此刻卻不能了。離庵不遠的山嶺，僧房，竹樹，尚勉強可見，稍外則封鎖在茫漠的煙霧裏了。</p><p>空齋蹋壁臥，忽夢溪山好。朝騎禿尾驢，來尋雪中道。石壁引孤松，長空沒飛鳥。不見遠山橫，寒煙起林杪。（雪中登黃山）</p><p>我倚著亭柱，默默地在咀嚼著漁洋這首五言詩的□□；尤其是結尾兩句，更道破了雪景的三昧。但說不定許多沒有經驗的人，要妄笑它是無味的詩句呢。文藝的真賞鑑，本來是件不容易的事，這又何必咄咄見怪？自己解說了一番，心裏也就釋然了。（鍾敬文〈西湖的雪景〉。三昧：借指奧祕。）</p>"
