      "passage": "<p>衛靈公問於史鰌曰：「政孰為務？」對曰：「大理為務！聽獄不中，死者不可生也，斷者不可屬也，故曰：大理為務。」少焉，子路見公，公以史鰌言告之。子路曰：「司馬為務！兩國有難，兩軍相當，司馬執枹以行之，一鬥不當，死者數萬。以殺人為非也，此其為殺人亦眾矣。故曰：司馬為務。」少焉，子貢入見，公以二子言告之。子貢曰：「不識哉！昔禹與有扈氏戰，三陳而不服，禹於是修教一年，而有扈氏請服。故曰：去民之所事，奚獄之所聽？兵革之不陳，奚鼓之所鳴？故曰：教為務也。」（劉向《說苑‧政理》）</p>"
