      "disc": 28,
      "passage": "那一棵四季桂，是十九年前我們移居舊宅時種植於大門右側的。樹由幼苗而茁壯成比一個人更高，春夏秋冬皆開花，是名副其實的四季桂。不久後，捷運系統將在那一帶建設車站。我們搬離舊宅，移入踩不到泥土的公寓。我和妹妹商量，把桂樹移植到她住的公家宿舍庭內。有泥土、有水和陽光和關愛，桂樹必能在另一個庭園內四季開花、散播清香的罷。雖然公家宿舍終不免有易換屋主之時，我們的四季桂定能繼續堅強地活下去。我想起日本平安時代，菅原道真在貶謫離鄉時，曾對庭中梅樹詠成一首和歌：「東風吹習習，猶未見梅放。莫謂主人離，等閒把春忘。」他日懷念舊宅的四季桂，我或者也會有這樣的心情罷。（林文月〈散文陸則——擬《東坡志林》〉）",
