      "disc": 22,
      "passage": "龍噓氣成雲，雲固弗靈於龍也。然龍乘是氣，茫洋窮乎玄間，薄日月，伏光景，感震電，神變化，水下土，汩陵谷，雲亦靈怪矣哉。雲，龍之所能使為靈也。若龍之靈，則非雲之所能使為靈也。然龍弗得雲，無以神其靈矣。失其所憑依，信不可歟。異哉！其所憑依，乃其所自為也。《易》曰：「雲從龍。」既曰龍，雲從之矣。（韓愈〈雜說一〉）",
