      "passage": "<p>我教書多年，還存一點好奇心，每當我教到最後一堂課時，就會發問卷給學生：今年你最喜歡哪些詩和文？……幾乎有十一、二年，票選第一名的作品都是契可夫的「Misery」。</p><p>這篇小小說講一個駕馬車的老頭，獨生子死了，在大雪紛飛的冬夜到戲院門口載客。上車的客人都急著教他趕路，他卻嘟嘟噥噥訴說著兒子的死。於是，客人們就產生了六、七種不同的反應。大多數人都教他閉嘴，快趕路！甚至有人用皮靴踢他、罵他糟老頭。另有一兩個旅客表示關心，問了他兒子的情況，不過，他們仍然很快地忘記了有這麼回事。人總是那麼健忘，尤其是對別人的事。這故事很簡單，敘述也沒什麼花俏之處，研究生們會這麼重視它，令我頗覺得欣慰。因為這個小小說完全講內心世界，呈現的是心境。老馬車夫在大雪中送完了客人，最後回到他簡陋的屋子，牽著馬入馬廄時，他說：這個世界上，只有你聽到我的話之後，還有一點同情的樣子。契可夫用他悲憫的眼睛，來看別人對他人悲傷的反應。（齊邦媛《霧漸漸散的時候》）</p>"
