      "passage": "<p>他站在門前的階梯上，伸手到褲子後口袋裡拿大門鑰匙。咦，不在這。在我脫下來的那件褲子裡。得去拿來。那衣櫥老是嘰嘎作響，不好去打擾她。剛才她翻身的時候，睡得正香呢。他悄悄帶上大門，又拉緊一點，直到門底下的護皮輕輕覆住門檻，像一張柔軟的眼皮。看起來是關緊了。反正到我回來前沒關係吧。（大衛‧洛吉《小說的五十堂課》節錄詹姆斯‧喬伊斯《尤里西斯》）</p>"
