      "passage": "<p>滄州南一寺臨河幹，山門圮於河，二石獸沉焉。閱十餘歲，僧募金重修，求二石獸於水中，竟不可得，以為順流下矣。棹數小舟，曳鐵鈀，尋十餘里無跡。一講學家設帳寺中，聞之，笑曰：「爾輩不能究物理。是非木柿，豈能為暴漲攜之去？乃石性堅重，沙性鬆浮，湮於沙上，漸沉漸深耳，沿河求之，不亦顛乎？」眾服為確論。一老河兵聞之，又笑曰：「凡河中失石，當求之於上流。蓋石性堅重，沙性鬆浮，水不能沖石，其反激之力，必於石下迎水處嚙沙為坎穴。漸激漸深，至石之半，石必倒擲坎穴中。如是再嚙，石又再轉。轉轉不已，遂反溯流逆上矣。求之下流，固顛；求之地中，不更顛乎？」如其言，果得數里外。（紀昀〈河中石獸〉）</p>"
