      "passage": "<p>順治間，滕、嶧之區，十人而七盜，官不敢捕。後受撫，邑宰別之為「盜戶」。凡值與良民爭，則曲意左袒之，蓋恐其復叛也。後訟者輒冒稱盜戶，而怨家則力攻其偽，每兩造具陳，曲直且置不辨，而先以盜之真偽，反復相訐，煩有司稽籍焉。適官署多狐，宰有女為所惑，聘術士來，符捉入瓶，將熾以火。狐在瓶內大呼曰：「我盜戶也！」聞者無不匿笑。（《聊齋志異•盜戶》）</p>"
