      "passage": "<p>家住西秦，賭博藝隨身。花柳上，鬥尖新。偶學念奴聲調，有時高遏行雲。蜀錦纏頭無數，不負辛勤。　數年來往咸京道，殘杯冷炙漫消魂。衷腸事，托何人？若有知音見採，不辭徧唱〈陽春〉。一曲當筵落淚，重掩羅巾。（晏殊〈山亭柳•贈歌者〉）</p>"
