      "passage": "甲、伯夷死名於首陽山下，盜跖死利於東陵之上，二人者，所死不同，其於殘生傷性均也。乙、古有伯夷、叔齊者，武王讓以天下而弗受，二人餓死首陽之陵。若此臣者，不畏重誅，不利厚賞，不可以罰禁也，不可以賞使也，此之謂無益之臣也。丙、伯夷，目不視惡色，耳不聽惡聲。非其君不事，非其民不使……故聞伯夷之風者，頑夫廉，懦夫有立志。",
